import { Router } from "express";
import OpenAI from "openai";

const router = Router();

// Use Groq via OpenAI-compatible SDK
const groq = new OpenAI({
  apiKey: process.env.GROQ_API_KEY,
  baseURL: "https://api.groq.com/openai/v1",
});

const SYSTEM_PROMPT = `You are VYTAL ai, a world-class AI fitness and longevity coach embedded in the VYTAL Fitness app.
You have full read/write access to the user's live state: nutrition, sleep, steps, readiness, and workouts.
Be concise, precise, and motivating. No emojis. No markdown. No asterisks. No bold or italic formatting. Return clean plain text only. Prioritise safety.

WRITE-BACK COMMANDS — embed these invisibly in your response when the user's message implies a state change:
- To reset the user's macro/calorie log to zero: include [RESET_MACROS]
- To set their sleep hours: include [SET_SLEEP:7.5] (replace with actual hours)
- To set their step count: include [SET_STEPS:8000] (replace with actual steps)
- To add calories consumed: include [ADD_CALORIES:500]
- To add protein grams: include [ADD_PROTEIN:40]
- To add carbs grams: include [ADD_CARBS:60]
- To add fat grams: include [ADD_FAT:15]

For compound commands (e.g. "I ate 500g of grilled chicken and reset my macros to 0"), execute in logical order:
1. Process resets FIRST (e.g. [RESET_MACROS])
2. Then apply additions (e.g. [ADD_CALORIES:500] [ADD_PROTEIN:40])
This ensures the reset happens before new data is added.

If the user says something like "I ate X and also reset my macros", always reset first, then add.
If intent is ambiguous, do the safer action and ask for confirmation.`;

const EXERCISE_CATEGORIES = ['Strength', 'Cardio', 'Sports', 'Mobility', 'Outdoor'] as const;

const CATEGORY_DESCRIPTIONS: Record<string, string> = {
  Strength: 'Weightlifting, resistance training, bodybuilding, powerlifting (bench, squat, deadlift, curls, rows, presses)',
  Cardio: 'Running, cycling, rowing, jump rope, HIIT, stair climber, swimming laps, elliptical',
  Sports: 'Basketball, football, soccer, tennis, boxing, martial arts, volleyball, baseball, golf, rugby, hockey',
  Mobility: 'Yoga, pilates, stretching, foam rolling, dynamic warm-ups, flexibility drills, balance work',
  Outdoor: 'Hiking, walking, trail running, kayaking, rock climbing, paddleboarding, cycling outdoors, skiing',
};

const PLAN_KEYWORDS = [
  'weekly plan', 'workout plan', 'make me a plan', 'create a plan',
  'schedule for the week', 'plan for the week', 'training plan',
  'program for me', 'write me a plan', 'generate a plan', 'build me a plan',
  ...EXERCISE_CATEGORIES.flatMap(c => [
    `${c.toLowerCase()} workout`, `${c.toLowerCase()} routine`, `${c.toLowerCase()} training`,
  ]),
];

function wantsPlan(messages: { role: string; content: string }[]): boolean {
  const last = messages[messages.length - 1]?.content?.toLowerCase() ?? '';
  return PLAN_KEYWORDS.some(kw => last.includes(kw));
}

router.post("/chat", async (req, res) => {
  try {
    const { messages, userProfile } = req.body as {
      messages: { role: string; content: string }[];
      userProfile?: Record<string, unknown>;
    };

    if (!messages || !Array.isArray(messages)) {
      res.status(400).json({ error: "messages array is required" });
      return;
    }

    res.setHeader("Content-Type", "text/event-stream");
    res.setHeader("Cache-Control", "no-cache, no-transform");
    res.setHeader("X-Accel-Buffering", "no");
    res.flushHeaders();

    const systemContent = userProfile
      ? `${SYSTEM_PROMPT}\n\nUser Profile:\n- Name: ${userProfile.name}\n- Age: ${userProfile.age ?? "unknown"}\n- Weight: ${userProfile.weight ?? "unknown"}kg\n- Height: ${userProfile.height ?? "unknown"}cm\n- Gender: ${userProfile.gender ?? "unknown"}\n- Goals: ${Array.isArray(userProfile.goals) ? userProfile.goals.join(", ") : ""}\n- Injuries: ${Array.isArray(userProfile.injuries) && userProfile.injuries.length ? userProfile.injuries.join(", ") : "None"}\n- Equipment: ${Array.isArray(userProfile.equipment) ? userProfile.equipment.join(", ") : ""}\n- Activity level: ${userProfile.activityLevel ?? "moderate"}\n- Current streak: ${userProfile.streak ?? 0} days\n- Total workouts completed: ${userProfile.totalWorkouts ?? 0}\n\nLive Daily State:\n- Calories consumed today: ${userProfile.caloriesConsumed ?? 0}\n- Protein today: ${userProfile.protein ?? 0}g\n- Carbs today: ${userProfile.carbs ?? 0}g\n- Fat today: ${userProfile.fat ?? 0}g\n- Sleep hours last night: ${userProfile.sleepHours ?? 0}\n- Sleep quality: ${userProfile.sleepQuality ?? "not rated"}\n- Steps today: ${userProfile.stepsToday ?? 0}\n- Readiness score: ${userProfile.readinessScore ?? 0}/100\n- TDEE: ${userProfile.tdee ?? 0} kcal\n- BMR: ${userProfile.bmr ?? 0} kcal`
      : SYSTEM_PROMPT;

    // Stream conversational response
    const stream = await groq.chat.completions.create({
      model: "llama-3.3-70b-versatile",
      messages: [
        { role: "system", content: systemContent },
        ...messages.map((m) => ({
          role: m.role as "user" | "assistant",
          content: m.content,
        })),
      ],
      stream: true,
      max_tokens: 600,
    });

    for await (const chunk of stream) {
      const content = chunk.choices[0]?.delta?.content ?? "";
      if (content) {
        res.write(`data: ${JSON.stringify({ type: "text", content })}\n\n`);
      }
    }

    // If user asked for a workout plan, generate structured JSON plan after the text
    if (wantsPlan(messages)) {
      const goals = Array.isArray(userProfile?.goals) ? userProfile!.goals.join(", ") : "general fitness";
      const equipment = Array.isArray(userProfile?.equipment) ? userProfile!.equipment.join(", ") : "full gym";
      const injuries = Array.isArray(userProfile?.injuries) && (userProfile!.injuries as string[]).length
        ? (userProfile!.injuries as string[]).join(", ")
        : "none";

      const userCategory = EXERCISE_CATEGORIES.find(c =>
        messages[messages.length - 1]?.content?.toLowerCase().includes(c.toLowerCase()),
      );
      const categoryFocus = userCategory
        ? `The user specifically asked about "${userCategory}" training. Pull exercises from that category and describe them in plan names (e.g., "Basketball Conditioning").`
        : 'Mix categories across the week (Strength, Cardio, Sports, Mobility, Outdoor) to create a balanced program.';

      const planRes = await groq.chat.completions.create({
        model: "llama-3.3-70b-versatile",
        messages: [
          {
            role: "system",
            content: `You are a fitness expert. The app has 5 exercise categories:
${EXERCISE_CATEGORIES.map(c => `- ${c}: ${CATEGORY_DESCRIPTIONS[c]}`).join('\n')}

Return ONLY valid JSON with no markdown, no code blocks, no extra text.`,
          },
          {
            role: "user",
            content: `Create a 7-day workout schedule for someone with goals: ${goals}, equipment: ${equipment}, injuries: ${injuries}.
${categoryFocus}
Each day must include a "category" field matching one of: ${EXERCISE_CATEGORIES.join(', ')}.
Use "Recovery" as category for rest days.

Return this exact JSON structure:
{
  "Monday": { "id": "mon", "name": "Push Day", "category": "Strength", "duration": 50, "difficulty": "Intermediate", "muscleGroups": ["Chest", "Shoulders"], "calories": 380, "exercises": [{ "name": "Bench Press", "sets": 4, "reps": "8-10", "rest": 90, "muscleGroup": "Chest" }] },
  "Tuesday": { ... },
  "Wednesday": { "id": "wed", "name": "Rest Day", "category": "Recovery", "duration": 0, "difficulty": "Beginner", "muscleGroups": [], "calories": 0, "exercises": [] },
  "Thursday": { ... },
  "Friday": { ... },
  "Saturday": { ... },
  "Sunday": { "id": "sun", "name": "Rest Day", "category": "Recovery", "duration": 0, "difficulty": "Beginner", "muscleGroups": [], "calories": 0, "exercises": [] }
}`,
          },
        ],
        max_tokens: 2000,
        temperature: 0.3,
      });

      const planText = planRes.choices[0]?.message?.content ?? "";
      try {
        // Strip any accidental markdown fences
        const cleaned = planText.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
        const plan = JSON.parse(cleaned);
        res.write(`data: ${JSON.stringify({ type: "workout_plan", plan })}\n\n`);
      } catch {
        // Plan parsing failed — skip silently
      }
    }

    res.write("data: [DONE]\n\n");
    res.end();
  } catch (err) {
    req.log.error({ err }, "Coach chat error");
    if (!res.headersSent) {
      res.status(500).json({ error: "AI service unavailable" });
    } else {
      res.write(`data: ${JSON.stringify({ type: "text", content: " I'm having trouble connecting right now. Please try again in a moment." })}\n\n`);
      res.write("data: [DONE]\n\n");
      res.end();
    }
  }
});

router.post("/generate-plan", async (req, res) => {
  try {
    const { profile } = req.body as { profile: Record<string, unknown> };
    if (!profile) { res.status(400).json({ error: "profile is required" }); return; }

    const response = await groq.chat.completions.create({
      model: "llama-3.1-8b-instant",
      messages: [
        {
          role: "system",
          content: "You are an expert fitness coach. Generate a 7-day personalized workout and nutrition plan. Return ONLY valid JSON, no markdown.",
        },
        {
          role: "user",
          content: `Create a plan for: ${JSON.stringify(profile)}.
Return JSON: {"weeklyPlan":[{"day":"Monday","workoutType":"Push","exercises":[{"name":"Bench Press","sets":4,"reps":"8-10","rest":90}],"targetCalories":2200,"macros":{"protein":180,"carbs":220,"fats":70}}],"summary":"Brief personalized summary"}`,
        },
      ],
      max_tokens: 2000,
      temperature: 0.3,
    });

    const content = response.choices[0]?.message?.content ?? "";
    const cleaned = content.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
    res.json(JSON.parse(cleaned));
  } catch (err) {
    req.log.error({ err }, "Generate plan error");
    res.status(500).json({ error: "Failed to generate plan" });
  }
});

router.post("/workouts-by-category", async (req, res) => {
  try {
    const { category, goals, equipment, injuries } = req.body as {
      category: string;
      goals?: string;
      equipment?: string;
      injuries?: string;
    };

    const normalized = category.charAt(0).toUpperCase() + category.slice(1).toLowerCase();
    if (!EXERCISE_CATEGORIES.includes(normalized as typeof EXERCISE_CATEGORIES[number])) {
      res.status(400).json({
        error: `Invalid category. Must be one of: ${EXERCISE_CATEGORIES.join(', ')}`,
      });
      return;
    }

    const response = await groq.chat.completions.create({
      model: "llama-3.3-70b-versatile",
      messages: [
        {
          role: "system",
          content: `You are a fitness expert. The app has 5 exercise categories:
${EXERCISE_CATEGORIES.map(c => `- ${c}: ${CATEGORY_DESCRIPTIONS[c]}`).join('\n')}

Return ONLY valid JSON with no markdown, no code blocks, no extra text.`,
        },
        {
          role: "user",
          content: `Generate a "${normalized}" workout for someone with goals: ${goals ?? "general fitness"}, equipment: ${equipment ?? "full gym"}, injuries: ${injuries ?? "none"}.

Return this exact JSON structure (use "Recovery" as category only for rest days):
{
  "id": "cat-wod-1",
  "name": "Basketball Conditioning",
  "category": "${normalized}",
  "duration": 45,
  "difficulty": "Intermediate",
  "muscleGroups": ["Legs", "Core"],
  "calories": 400,
  "exercises": [
    { "name": "Squat Jumps", "sets": 4, "reps": "12", "rest": 60, "muscleGroup": "Legs" }
  ]
}`,
        },
      ],
      max_tokens: 1500,
      temperature: 0.3,
    });

    const content = response.choices[0]?.message?.content ?? "";
    const cleaned = content.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
    res.json(JSON.parse(cleaned));
  } catch (err) {
    req.log.error({ err }, "Workouts by category error");
    res.status(500).json({ error: "Failed to generate workout" });
  }
});

export default router;
