import { Router } from "express";
import { eq } from "drizzle-orm";
import { getAuth } from "@clerk/express";
import { db, users } from "@workspace/db";

const router = Router();

router.get("/profile", async (req, res) => {
  const authId = getAuth(req).userId;
  if (!authId) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  try {
    const [user] = await db.select().from(users).where(eq(users.id, authId)).limit(1);
    if (!user) {
      res.status(404).json({ error: "User not found" });
      return;
    }
    res.json({ user });
  } catch (err) {
    req.log.error({ err }, "Failed to fetch user profile");
    res.status(500).json({ error: "Failed to fetch profile" });
  }
});

router.put("/profile", async (req, res) => {
  const authId = getAuth(req).userId;
  if (!authId) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const { profile, state } = req.body as {
    profile?: Record<string, unknown>;
    state?: Record<string, unknown>;
  };

  try {
    const values: Record<string, unknown> = {
      id: authId,
      updatedAt: new Date(),
      lastSyncedAt: new Date(),
    };

    if (profile) {
      if (profile.name !== undefined) values.name = profile.name;
      if (profile.age !== undefined) values.age = profile.age;
      if (profile.weight !== undefined) values.weight = profile.weight;
      if (profile.height !== undefined) values.height = profile.height;
      if (profile.gender !== undefined) values.gender = profile.gender;
      if (profile.goals !== undefined) values.goals = profile.goals;
      if (profile.injuries !== undefined) values.injuries = profile.injuries;
      if (profile.equipment !== undefined) values.equipment = profile.equipment;
      if (profile.stressLevel !== undefined) values.stressLevel = profile.stressLevel;
      if (profile.activityLevel !== undefined) values.activityLevel = profile.activityLevel;
      if (profile.onboardingComplete !== undefined) values.onboardingComplete = profile.onboardingComplete ? 1 : 0;
      if (profile.email !== undefined) values.email = profile.email;
    }

    if (state) {
      if (state.fitScore !== undefined) values.fitScore = state.fitScore;
      if (state.streak !== undefined) values.streak = state.streak;
      if (state.totalWorkouts !== undefined) values.totalWorkouts = state.totalWorkouts;
      if (state.xp !== undefined) values.xp = state.xp;
      if (state.level !== undefined) values.level = state.level;
    }

    const [user] = await db
      .insert(users)
      .values(values)
      .onConflictDoUpdate({
        target: users.id,
        set: values,
      })
      .returning();

    req.log.info({ authId }, "User profile synced");
    res.json({ user });
  } catch (err) {
    req.log.error({ err }, "Failed to upsert user profile");
    res.status(500).json({ error: "Failed to save profile" });
  }
});

export default router;
